style.css:
@-moz-document domain("chat.openai.com") {
body {
    background: url("https://c4.wallpaperflare.com/wallpaper/316/559/580/nebula-astronomy-4k-planets-cosmos-wallpaper-preview.jpg") no-repeat center center fixed !important;
    background-size: cover !important;
  }

  /* Fondos de áreas del chat transparentes */
  main,
  .text-base,
  .bg-gray-900,
  .dark .bg-gray-800,
  .bg-token-main-surface-primary,
  div[class*="message"] {
    background: transparent !important;
    backdrop-filter: none !important;
    -webkit-backdrop-filter: none !important;
    box-shadow: none !important;
    color: #ffffff !important;
  }

  /* Código transparente */
  pre,
  code,
  code * {
    background: transparent !important;
    color: #00ffff !important;
    box-shadow: none !important;
    border: none !important;
  }

  /* Contenedores de mensajes transparentes */
  div[class*="message"] .rounded-md,
  div[class*="message"] .overflow-y-auto {
    background: transparent !important;
  }
}
